  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Pirfenidone, the closest structural analogue with an N-phenyl methylpyridone core, is reported to have high oral bioavailability in humans, directly supporting high F for the N-phenyl methylpyrazolone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Urapidil, the highest-transfer analogue, has absolute oral bioavailability of 78% in healthy volunteers after an oral solution, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ondansetron, a high-transfer heteroaromatic drug, has absolute oral bioavailability of approximately 60% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Alogliptin has absolute bioavailability of approximately 100% in healthy volunteers, supporting high F for a small, well-absorbed heteroaromatic compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alprazolam has absolute oral bioavailability of 92% in humans, supporting high F for a low-clearance, well-absorbed small molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "The only low-F record, acamprosate at about 11% bioavailability, comes from a highly polar, ionizable molecule and is not representative of the neutral pyrazolone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is antipyrine, a small neutral N-phenyl pyrazolone. Multiple high-transfer analogues with related heteroaromatic or N-phenyl structures show absolute oral bioavailability of 52–100%, all well above the 20% threshold. The single low-F record is from a polar, ionizable molecule and is not representative. Therefore high bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query itself is present in the provided records; the prediction relies on transferable analogues.",
    "The only low-F record (C23) is associated with a SMILES that does not match acamprosate and is structurally non-representative, limiting its relevance."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

